mapper.insert:
INSERT INTO cps_review_adjudication (
  issue_id, version_no, task_id, reviewer_emp_no, reviewer_emp_name,
  decision, ai_overall, ai_relation, reason, from_status, to_status, created_at
) VALUES (
  #{issueId}, #{versionNo}, #{taskId}, #{reviewerEmpNo}, #{reviewerEmpName},
  #{decision}, #{aiOverall}, #{aiRelation}, #{reason}, #{fromStatus}, #{toStatus}, #{createdAt}
)

mapper.select:
SELECT a.id, a.issue_id, a.version_no, a.task_id,
       a.reviewer_emp_no, a.reviewer_emp_name,
       a.decision, a.ai_overall, a.ai_relation,
       a.reason, a.from_status, a.to_status, a.created_at
FROM cps_review_adjudication a
INNER JOIN cps_issue i ON i.id = a.issue_id

    AND a.issue_id = #{issueId}
    AND a.decision = #{decision}
    AND a.ai_relation = #{aiRelation}
    AND a.reviewer_emp_no = #{reviewerEmpNo}
    AND i.factory = #{factory}
    AND i.area = #{area}
    AND i.category_l1_id = #{categoryL1Id}
    AND i.category_l2_id = #{categoryL2Id}
    AND a.created_at >= #{startTime}
    AND a.created_at <= #{endTime}

ORDER BY a.created_at DESC, a.id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(1)
FROM cps_review_adjudication a
INNER JOIN cps_issue i ON i.id = a.issue_id

    AND a.issue_id = #{issueId}
    AND a.decision = #{decision}
    AND a.ai_relation = #{aiRelation}
    AND a.reviewer_emp_no = #{reviewerEmpNo}
    AND i.factory = #{factory}
    AND i.area = #{area}
    AND i.category_l1_id = #{categoryL1Id}
    AND i.category_l2_id = #{categoryL2Id}
    AND a.created_at >= #{startTime}
    AND a.created_at <= #{endTime}
